#include "VersionControlFiles.h"

#include <sstream>
#include <vector>

namespace jasperengine::editor::vcsfiles {

    const char* const startMarker = "# Generated by JasperEngine Editor.";
    const char* const endMarker = "# End of the JasperEngine Editor's lines: your own lines go below and are kept.";

    namespace {

        // What the editor regenerates, and what belongs to one machine or one developer
        const char* const ignoreText =
            "# Generated by JasperEngine Editor.\n"
            "\n"
            "# Engine API snapshot, generated C++, build trees, this machine's build\n"
            "# settings and this user's editor workspace.\n"
            ".jasperengine/\n"
            "\n"
            "# Regenerated on every build.\n"
            "/CMakeLists.txt\n"
            "\n"
            "# Deleted assets, until the trash is emptied.\n"
            ".trash/\n"
            "\n"
            "# Build output.\n"
            "build/\n"
            "\n"
            "# The Recorder's movies and image sequences.\n"
            "Recordings/\n"
            "\n"
            "# Per-developer IDE configuration.\n"
            ".vscode/\n"
            ".idea/\n"
            "*.user\n"
            "\n"
            "# Written by the game while it runs, Play mode included.\n"
            "UserSettings.xml\n"
            "\n"
            "# The editor's own settings and layout, left here by an editor started in this\n"
            "# folder (older versions; they now go to the user's config directory).\n"
            "/settings.yaml\n"
            "/editor_layout_v2.ini\n"
            "\n"
            "*.log\n"
            ".DS_Store\n"
            "Thumbs.db\n"
            "\n"
            "# What a conflicted merge leaves next to a file.\n"
            "*.orig\n";

        // Scenes and project.yaml only diff and merge while every checkout agrees on the
        // line ending, so it is not left to core.autocrlf. Scenes and prefabs merge with the editor's
        // scene merge driver once it is set up (git config, "Set Up Smart Merge"); without it git's text
        // merge runs. With LFS the binaries are LFS objects and lockable (git lfs lock); scenes, prefabs
        // and meta files never are LFS objects (docs/specs/S29-version-control.md R21).
        const char* const binaryPatterns[] = {
            "*.png", "*.jpg", "*.jpeg", "*.tga", "*.ktx", "*.dds", "*.glb", "*.gltf", "*.fbx", "*.obj", "*.jetrees", "*.jtile",
            "*.ogg", "*.wav", "*.mp3", "*.ttf", "*.otf",
            // T6 R77: a volume is a binary, and big
            "*.voxelvolume"
        };
        // binaries LFS adds (art sources, HDR images, cooked textures, video)
        const char* const lfsOnlyPatterns[] = {
            "*.psd", "*.exr", "*.hdr", "*.ktx2", "*.basis", "*.blend", "*.mp4", "*.webm"
        };

        // Lines earlier editors generated that no current variant has (the attributes before the
        // scene merge driver, and a format before prefabs)
        const char* const legacyAttributeLines[] = {
            "*.scene text eol=lf", "*.prefab text eol=lf", "*.bundle text eol=lf"
        };

        std::vector<std::string> splitLines(const std::string& text) {
            std::vector<std::string> lines;
            std::istringstream stream(text);
            std::string line;
            while (std::getline(stream, line)) {
                if (!line.empty() && line.back() == '\r') line.pop_back();
                lines.push_back(line);
            }
            return lines;
        }

        // trimmed, runs of blanks as one space: older templates padded their columns differently
        std::string normalise(const std::string& line) {
            std::string out;
            bool blank = false;
            for (char c : line) {
                if (c == ' ' || c == '\t' || c == '\r') {
                    blank = !out.empty();
                    continue;
                }
                if (blank) out += ' ';
                blank = false;
                out += c;
            }
            return out;
        }

        bool startsWith(const std::string& text, const std::string& prefix) {
            return text.compare(0, prefix.size(), prefix) == 0;
        }

    }

    std::string ignoreBlock() {
        return ignoreText;
    }

    std::string attributesBlock(bool lfs, bool lockScenes) {
        auto line = [](const char* pattern, const std::string& attributes) {
            std::string text = pattern;
            text.append(text.size() < 10 ? 10 - text.size() : 1, ' ');
            return text + attributes + "\n";
        };
        const std::string sceneLock = lockScenes ? " lockable" : "";
        std::string text = std::string(startMarker) + "\n"
            "\n"
            "* text=auto eol=lf\n"
            "\n";
        text += line("*.scene", "text eol=lf merge=jasperengine-scene" + sceneLock);
        text += line("*.prefab", "text eol=lf merge=jasperengine-scene" + sceneLock);
        text += line("*.meta", "text eol=lf");
        for (const char* pattern : {"*.yaml", "*.lua", "*.cmake", "*.h", "*.cpp"}) text += line(pattern, "text eol=lf");
        text += "\n";
        const std::string binary = lfs ? "filter=lfs diff=lfs merge=lfs -text lockable" : "binary";
        for (const char* pattern : binaryPatterns) text += line(pattern, binary);
        if (lfs) {
            for (const char* pattern : lfsOnlyPatterns) text += line(pattern, binary);
        }
        return text;
    }

    const std::set<std::string>& knownGeneratedLines(FileKind kind) {
        static const std::set<std::string> ignore = [] {
            std::set<std::string> lines;
            for (const std::string& line : splitLines(ignoreBlock())) lines.insert(normalise(line));
            lines.insert(normalise(endMarker));
            lines.erase("");
            return lines;
        }();
        static const std::set<std::string> attributes = [] {
            std::set<std::string> lines;
            for (bool lfs : {false, true}) {
                for (bool lockScenes : {false, true}) {
                    for (const std::string& line : splitLines(attributesBlock(lfs, lockScenes))) lines.insert(normalise(line));
                }
            }
            for (const char* line : legacyAttributeLines) lines.insert(normalise(line));
            lines.insert(normalise(endMarker));
            lines.erase("");
            return lines;
        }();
        return kind == FileKind::Ignore ? ignore : attributes;
    }

    Refresh refresh(const std::optional<std::string>& existing, const std::string& block, FileKind kind, std::string& out) {
        const std::string managed = block + endMarker + "\n";
        if (!existing) {
            out = managed;
            return Refresh::Write;
        }
        std::string text = *existing;
        if (startsWith(text, "\xEF\xBB\xBF")) text.erase(0, 3);
        if (!startsWith(text, startMarker)) {
            return Refresh::LeaveAlone;
        }

        // the end marker's line: what follows is the user's, byte for byte
        size_t pos = 0;
        while (pos < text.size()) {
            size_t end = text.find('\n', pos);
            const size_t next = end == std::string::npos ? text.size() : end + 1;
            if (end == std::string::npos) end = text.size();
            std::string line = text.substr(pos, end - pos);
            if (!line.empty() && line.back() == '\r') line.pop_back();
            if (line == endMarker) {
                out = managed + text.substr(next);
                return Refresh::Write;
            }
            pos = next;
        }

        // a file of an editor from before the end marker: its lines that no editor generated,
        // in their order, without leading and trailing blank lines
        const std::set<std::string>& generated = knownGeneratedLines(kind);
        std::vector<std::string> userLines;
        bool first = true;
        for (const std::string& line : splitLines(text)) {
            if (first) {
                first = false;
                continue;   // the start marker
            }
            const std::string key = normalise(line);
            if (!key.empty() && generated.count(key)) continue;
            if (key.empty() && userLines.empty()) continue;
            userLines.push_back(line);
        }
        while (!userLines.empty() && normalise(userLines.back()).empty()) userLines.pop_back();
        // runs of blank lines (where generated lines were taken out) as one
        std::string user;
        bool previousBlank = false;
        for (const std::string& line : userLines) {
            const bool blank = normalise(line).empty();
            if (blank && previousBlank) continue;
            previousBlank = blank;
            user += line + "\n";
        }
        out = managed + user;
        return Refresh::Write;
    }

}
